const docId = input.documentId;
if (!docId) return { error: 'No documentId provided' };
const res = await fetch(apiUrl + '/documents/' + docId, {
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' }
});
if (!res.ok) {
  const err = await res.text();
  return { error: 'Failed to fetch document: ' + res.status + ' ' + err };
}
const data = await res.json();
const doc = data.data || data;
return {
  documentId: String(doc._id),
  title: doc.title,
  content: doc.content,
  summary: doc.summary || '',
  type: doc.type,
  status: doc.status,
  tags: doc.tags || [],
  version: doc.version
};

const modeOverride = (trigger && trigger.mode) || '';
if (modeOverride === 'question' || modeOverride === 'edit') {
  return { intent: modeOverride, complexity: modeOverride === 'edit' ? 'moderate' : 'simple', override: true };
}

const instruction = (trigger && trigger.instruction) || '';
const lower = instruction.toLowerCase().trim();

const questionPatterns = /^(what|why|how|when|where|who|which|is |are |does |do |can |could |would |should |tell me|explain|describe|summarize|list |show me)/;
const hasQuestionMark = lower.includes('?');
const editPatterns = /\b(change|update|add|remove|delete|edit|rewrite|fix|improve|replace|insert|append|prepend|move|rename|modify|restructure|refactor|shorten|expand|simplify|translate|convert|merge|split|reformat)\b/;

let intent = 'question';
let complexity = 'simple';

if (questionPatterns.test(lower) || hasQuestionMark) {
  intent = 'question';
  complexity = 'simple';
} else if (editPatterns.test(lower)) {
  intent = 'edit';
  complexity = lower.length > 200 ? 'complex' : 'moderate';
} else {
  intent = lower.length > 100 ? 'edit' : 'question';
  complexity = intent === 'edit' ? 'moderate' : 'simple';
}

return { intent, complexity };
